function deviceCard(d){
  const c=node('article','device'+(['on','playing','open'].includes(d.state)?' active':'')), top=node('div','device-top');
  top.append(icon(deviceType(d)),node('span','status'+(d.available?' on':''),states[d.state]||d.state));const title=node('div');title.append(node('h3',null,d.name),node('p',null,d.room+' · '+adapters[d.adapter]));const visual=button('',()=>{selectedRemote=d.id;navigate('remote');},'appliance-button');visual.setAttribute('aria-label','Abrir painel de '+d.name);visual.append(applianceArt(d));c.append(top,title,visual);if(d.generic_remote)c.append(node('p','button-progress',`${d.actions.length} de ${d.generic_remote.buttons.length} botões configurados`));if(d.telemetry)c.append(telemetryPanel(d));if(d.channels){const channels=node('div','readings');d.channels.forEach(ch=>channels.append(node('span','reading',`Canal ${ch.channel}: ${states[ch.state]||ch.state}`)));c.append(channels);}
  const bottom=node('div','device-bottom');
  if(d.adapter==='pending'){bottom.append(button(d.kind==='lock'?'Ver integração':'Configurar',()=>configureDialog(d),'button small'),button(d.kind==='lock'?'Buscar Bluetooth':'Buscar no Wi-Fi',()=>searchDevices([d.kind==='lock'?'bluetooth':d.id==='tv'?'samsung':d.id==='broadlink'?'broadlink':(['tuya','curtain'].includes(d.id)||d.id?.startsWith('tuya_'))?'tuya':'sonoff']),'button small'));}
  else if(d.kind==='tv'||d.kind==='remote')bottom.append(button('Abrir controle',()=>{selectedRemote=d.id;navigate('remote');},'button small primary'));
  else{const actions=d.kind==='lock'?['lock','unlock']:d.kind==='cover'?['open','stop','close']:d.actions;actions.filter(a=>d.actions.includes(a)).forEach(a=>{const channel=a.match(/^(on|off)_(\d)$/);const label=channel?`Canal ${channel[2]} · ${labels[channel[1]]}`:labels[a]||a;bottom.append(button(label,e=>act(d.id,a,e.currentTarget),'button small'+(a==='on'||a.startsWith('on_')?' primary':'')));});}
  if(d.adapter!=='pending')bottom.append(button('⚙',()=>configureDialog(d),'button small settings-button'));
  if(!['tv','remote'].includes(d.kind)&&d.adapter!=='pending')bottom.append(button('Ver painel',()=>{selectedRemote=d.id;navigate('remote');},'button small'));c.append(bottom);if(d.message){const p=node('p',null,d.message);c.append(p);}return c;
}
async function act(id,action,b){
  if(b)b.disabled=true;
  try{
    if(demo){const d=devices.find(d=>d.id===id);const map={on:'on',off:'off',open:'open',close:'closed',lock:'locked',unlock:'unlocked',power_on:'on',power_off:'off'};if(map[action])d.state=map[action];const preset=climatePresets(d).find(p=>p.action===action);if(preset&&d.telemetry){d.telemetry.target_temperature=preset.temperature;d.telemetry.activity=preset.mode==='heat'?'heating':'cooling';d.state=preset.mode;}if(action==='power_off'&&d.telemetry)d.telemetry.activity='off';toast('Demonstração: '+(labels[action]||action)+' simulado.');render();return;}
    let confirmation='';
    if(action==='unlock'){
      const accepted=await confirmUnlock(id);if(!accepted)return;
      confirmation=(await api('/api/unlock-confirmation',{id})).confirmation;
    }
    const result=await api('/api/action',{id,action,confirmation});toast(result.message);await refreshStatus(false);
  }catch(e){toast(e.message);}finally{if(b)b.disabled=false;}
}
function confirmUnlock(id){return new Promise(resolve=>{dialog.replaceChildren();const body=node('div');body.append(node('h2',null,'Abrir a porta?'),node('p',null,'Confirme a abertura de '+devices.find(d=>d.id===id).name+'.'));const row=node('div','dialog-actions');row.append(button('Cancelar',()=>{resolve(false);dialog.close();}),button('Confirmar abertura',()=>{resolve(true);dialog.close();},'button primary'));body.append(row);dialog.append(body);dialog.addEventListener('cancel',()=>resolve(false),{once:true});dialog.showModal();});}
