    add('power_on');add('power_off');box.append(controls);
    const dpad=node('div','dpad');['','up','','left','enter','right','','down',''].forEach(a=>{if(a)add(a,dpad,labels[a],a==='enter'?'ok':'');else dpad.append(node('span'));});box.append(dpad);
    const row=node('div','remote-controls');['back','home','volume_down','volume_up','mute','source','channel_down','channel_up'].forEach(a=>add(a,row));box.append(row,node('p','subtext','Na primeira conexão, aceite “Casa Universal” na TV. Para ligar via rede, configure também o MAC da TV.'));
