async function searchDevices(providers=Object.keys(scanProviders)){
 if(demo){toast('As buscas reais estão disponíveis no painel principal.');return;}
 if(scanning){toast('Uma busca já está em andamento.');return;}
 if(currentView!=='settings')navigate('settings');
 scanning=true;const results=$('.scan-results');results.replaceChildren();const tools=results.previousElementSibling;tools.querySelectorAll('button').forEach(b=>b.disabled=true);
 const jobs=providers.map(async provider=>{const meta=scanProviders[provider],section=node('div','scan-group');section.append(node('h3',null,meta.method),node('p','subtext','Buscando…'));results.append(section);try{const r=await api('/api/discover/'+provider,{});section.querySelector('p').textContent=r.devices.length?`${r.devices.length} encontrado(s).`:meta.empty;for(const found of r.devices)section.append(discoveryCard(provider,found));}catch(e){section.querySelector('p').textContent=e.message;}});
 try{await Promise.allSettled(jobs);toast('Busca concluída. Escolha um aparelho para preencher a conexão.');}finally{scanning=false;tools.querySelectorAll('button').forEach(b=>b.disabled=false);}
}
